def transform(grid):
    h, w = len(grid), len(grid[0])

    # Full-width / full-height nonzero lines are the separators.
    row_seps = [r for r in range(h) if len(set(grid[r])) == 1 and grid[r][0] != 0]
    col_seps = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1
                and grid[0][c] != 0]

    def segments(size, seps):
        out, start = [], 0
        for p in seps:
            if start < p:
                out.append((start, p))
            start = p + 1
        if start < size:
            out.append((start, size))
        return out

    rs = segments(h, row_seps)
    cs = segments(w, col_seps)
    out = [row[:] for row in grid]

    # For each color, identify which adjacent cell columns form mirror pairs.
    pair_cols = {}
    for r0, r1 in rs:
        for j in range(len(cs) - 1):
            c0, c1 = cs[j]
            d0, d1 = cs[j + 1]
            if c1 - c0 != d1 - d0:
                continue
            for color in range(1, 10):
                left = [[grid[r][c] for c in range(c0, c1)] for r in range(r0, r1)]
                right = [[grid[r][c] for c in range(d0, d1)] for r in range(r0, r1)]
                lp = [[color if x == color else 0 for x in row] for row in left]
                rp = [[color if x == color else 0 for x in row] for row in right]
                if any(x for row in lp for x in row) and rp == [row[::-1] for row in lp]:
                    pair_cols.setdefault(color, set()).add((j, j + 1))

    # Complete each established mirror-pair pattern wherever one cell is empty.
    for color, pairs in pair_cols.items():
        for r0, r1 in rs:
            for j, k in pairs:
                c0, c1 = cs[j]
                d0, d1 = cs[k]
                if c1 - c0 != d1 - d0 or r1 - r0 != r1 - r0:
                    continue
                left = [[out[r][c] for c in range(c0, c1)] for r in range(r0, r1)]
                right = [[out[r][c] for c in range(d0, d1)] for r in range(r0, r1)]
                left_has = any(x == color for row in left for x in row)
                right_has = any(x == color for row in right for x in row)
                if left_has and not right_has:
                    for dr in range(r1 - r0):
                        for dc in range(c1 - c0):
                            if left[dr][dc] == color:
                                out[r0 + dr][d1 - 1 - dc] = color
                elif right_has and not left_has:
                    for dr in range(r1 - r0):
                        for dc in range(d1 - d0):
                            if right[dr][dc] == color:
                                out[r0 + dr][c1 - 1 - dc] = color

    return out
